"""Observation-only controller, shared by offline and official backends."""
import time
import numpy as np
from geometry import feasible,enclosing_circle,optical_cover,search_stations

class Solver:
    def __init__(self, backend, problem, spacing=950., max_refine=8):
        self.api=backend
        self.problem=problem
        self.stations=search_stations(problem,spacing)
        self.max_refine=max_refine
        self.pos=np.zeros(2)
        self.channel=1
        self.cleared=set()
        self.obs={c:[] for c in range(1,21)}
        self.counts={'measure':0,'clear':0,'failed_clear':0,'fallback':0}
        self.visited=[]
        self.deadline=float('inf')

    def action(self,path,p,c):
        if time.monotonic()>self.deadline-3:
            raise TimeoutError('Insufficient remaining real duration')
        r=self.api.action(path,p,c)
        self.pos=np.array(p,dtype=float)
        if path=='/measure':
            self.channel=c
            self.counts['measure']+=1
            if r['measure_result']=='direction':
                self.obs[c].append((self.pos.copy(),float(r['svd_deg'])))
        else:
            self.counts['clear']+=1
            if r['clear_result']=='success':
                self.cleared.add(c)
            else:
                self.counts['failed_clear']+=1
        return r

    def clear(self,p,c):
        return self.action('/clear',p,c)['clear_result']=='success'

    def locate(self,c):
        observations=self.obs[c]
        for k in range(self.max_refine):
            poly=feasible(observations)
            if len(poly)==0:
                raise ValueError('Empty feasible polygon; stop and inspect error model')
            center,radius=enclosing_circle(poly)
            if radius<=19.99:
                if not self.clear(center,c):
                    raise RuntimeError('Certified clear failed; protocol/model mismatch')
                return
            p0,theta=observations[-1]
            d=center-p0
            length=np.linalg.norm(d)
            if length<1e-7:
                break
            u=d/length; v=np.array([-u[1],u[0]])
            # Move towards feasible center, with moderate lateral baseline.
            # No assumption that this point must receive a directional signal.
            sign=1 if k%2==0 else -1
            candidate=p0+.65*d+sign*min(100.,.35*length)*v
            response=self.action('/measure',candidate,c)
            kind=response['measure_result']
            if kind=='near':
                if not self.clear(self.pos,c):
                    raise RuntimeError('Near result followed by failed clear')
                return
            if kind=='no_signal':
                # Retain earlier positive cones; darkness cannot exclude position.
                other=p0+.65*d-sign*min(100.,.35*length)*v
                response=self.action('/measure',other,c)
                if response['measure_result']=='near':
                    if not self.clear(self.pos,c):
                        raise RuntimeError('Near result followed by failed clear')
                    return
                if response['measure_result']=='no_signal':
                    break
        poly=feasible(observations)
        center,radius=enclosing_circle(poly)
        if radius<=19.99:
            if not self.clear(center,c):
                raise RuntimeError('Certified clear failed')
            return
        self.counts['fallback']+=1
        points=optical_cover(poly,observations[0][1])
        # Reverse snake if its far endpoint is closer to the present position.
        if np.linalg.norm(points[-1]-self.pos)<np.linalg.norm(points[0]-self.pos):
            points=points[::-1]
        for p in points:
            if self.clear(p,c):
                return
        raise RuntimeError('Exhausted certified optical cover without success')

    def run(self):
        start=time.perf_counter()
        entered=self.api.enter()
        self.deadline=time.monotonic()+entered['remaining_real_duration_s']
        pending=list(range(len(self.stations)))
        completed=False
        try:
            while pending:
                i=min(pending,key=lambda j:np.linalg.norm(self.stations[j]-self.pos))
                pending.remove(i)
                p=self.stations[i]
                found=[]
                channels=[c for c in range(1,21) if c not in self.cleared]
                if self.channel in channels:
                    channels.remove(self.channel); channels.insert(0,self.channel)
                for c in channels:
                    r=self.action('/measure',p,c)
                    if r['measure_result']=='near':
                        if not self.clear(p,c):
                            raise RuntimeError('Near clear failed')
                    elif r['measure_result']=='direction':
                        found.append(c)
                self.visited.append(i)
                # Batch scanning avoids returning to a station for each channel.
                while found:
                    centers={c:enclosing_circle(feasible(self.obs[c]))[0] for c in found}
                    c=min(found,key=lambda c:np.linalg.norm(centers[c]-self.pos))
                    self.locate(c)
                    found.remove(c)
                if len(self.cleared)==16:
                    break  # public hard upper bound, never stop merely at 10
            completed=True
        finally:
            # Do not issue a different action after an unresolved transport failure.
            if completed and time.monotonic()<self.deadline-1:
                self.api.exit()
        total=self.api.virtual_time
        return dict(problem=self.problem,cleared=len(self.cleared),virtual_time_s=total,
                    mean_time_s=total/len(self.cleared) if self.cleared else None,
                    program_time_s=time.perf_counter()-start,complete=completed,
                    stations_visited=len(self.visited),**self.counts)

