"""Observation-only optimization; original coverage and error bounds retained."""
import math
import time
import numpy as np
from baseline_solver import Solver as BaselineSolver
from geometry import feasible,enclosing_circle,optical_cover,bearing_clip,EPS_DEG


def safe_clear_point(current,center,radius):
    """Projection onto a sufficient safe disk; radius error margin retained."""
    if radius>19.99:
        raise ValueError('Region cannot be certified by a 19.99m disk')
    d=np.asarray(current)-center
    distance=np.linalg.norm(d)
    slack=max(0.,19.99-radius)
    return np.asarray(current).copy() if distance<=slack else center+d*(slack/max(distance,1e-15))


def open_route(points,start,end=None):
    """Nearest-neighbor seed and bounded 2-opt; optimize estimated open path."""
    if not len(points):return []
    points=np.asarray(points)
    pending=list(range(len(points)));order=[];p=np.asarray(start)
    while pending:
        j=min(pending,key=lambda i:np.linalg.norm(points[i]-p))
        order.append(j);pending.remove(j);p=points[j]
    def edge(a,b):return float(np.linalg.norm(a-b))
    # At most three improving passes, independent of the simulator speed.
    for _ in range(3):
        improved=False
        for i in range(len(order)-1):
            before=start if i==0 else points[order[i-1]]
            for j in range(i+1,len(order)):
                after=points[order[j+1]] if j+1<len(order) else end
                old=edge(before,points[order[i]])
                new=edge(before,points[order[j]])
                if after is not None:
                    old+=edge(points[order[j]],after)
                    new+=edge(points[order[i]],after)
                if new+1e-7<old:
                    order[i:j+1]=reversed(order[i:j+1]);improved=True
        if not improved:break
    return order


class Solver(BaselineSolver):
    def __init__(self,backend,problem,profile='local',max_refine=8):
        super().__init__(backend,problem,max_refine=max_refine)
        if profile not in ('local','route','joint','safe','joint_safe','directional','directional_route','directional_safe','directional_tour','directional_tour_safe','directional_opportunistic_safe','directional_layers_safe'):
            raise ValueError('Unknown optimization profile')
        self.profile=profile
        self.cache={}
        self.measured={c:[] for c in range(1,21)}
        self.pending_stations=[]
        self.deferred={}
        self.parts={'move_s':0.,'switch_s':0.,'measure_s':0.,'optical_s':0.,'laser_s':0.}
        self.diagnostics={'candidate_evaluations':0,'deferred_targets':0,'forced_targets':0,
                          'opportunistic_measures':0,'safe_clear_points':0}
        self.certificates=[]
        self.max_defer_stations=3
        self.coverage_order=open_route(self.stations,np.zeros(2)) if 'tour' in profile else []

    def region(self,c):
        n=len(self.obs[c])
        if c not in self.cache or self.cache[c][0]!=n:
            poly=feasible(self.obs[c])
            if len(poly)==0:raise ValueError('Empty feasible region')
            center,radius=enclosing_circle(poly)
            self.cache[c]=(n,poly,center,radius)
        return self.cache[c][1:]

    def action(self,path,p,c):
        old_pos=self.pos.copy();old_channel=self.channel
        r=super().action(path,p,c)
        self.parts['move_s']+=float(np.linalg.norm(np.asarray(p)-old_pos))/5
        if path=='/measure':
            self.parts['measure_s']+=5
            self.parts['switch_s']+=int(old_channel!=c)
            self.measured[c].append(self.pos.copy())
        else:
            self.parts['optical_s']+=3
            self.parts['laser_s']+=2*int(r['clear_result']=='success')
        return r

    def certified_clear(self,c,poly,center,radius):
        p=safe_clear_point(self.pos,center,radius) if self.profile.endswith('safe') else center
        bound=float(np.max(np.linalg.norm(poly-p,axis=1)))
        if bound>19.990001:raise RuntimeError('Unsafe clear candidate')
        self.certificates.append({'channel':c,'vertex_bound_m':bound})
        if self.profile.endswith('safe'):self.diagnostics['safe_clear_points']+=1
        if not self.clear(p,c):raise RuntimeError('Certified clear failed')

    def next_measure(self,c,poly,center,radius):
        current=self.pos.copy();p0=self.obs[c][-1][0]
        candidates=[current]
        for origin in (current,p0):
            d=center-origin;length=np.linalg.norm(d)
            if length<1e-8:continue
            u=d/length;v=np.array([-u[1],u[0]])
            for fraction in (.5,.8,1.):
                for offset in (0.,-1.,1.):
                    lateral=min(100.,max(25.,.25*length))
                    candidates.append(origin+fraction*d+offset*lateral*v)
            # Keep the original proposal as an explicit candidate.
            for sign in (-1,1):candidates.append(origin+.65*d+sign*min(100.,.35*length)*v)
        if len(self.obs[c])>1:
            candidates.append((self.obs[c][0][0]+p0)/2)
        samples=np.vstack([poly*.8+center*.2,center[None,:]])
        if len(samples)>9:samples=samples[np.linspace(0,len(samples)-1,9,dtype=int)]
        previous=np.array([p for p,a in self.obs[c]])
        normals=np.array([[math.cos(a),math.sin(a)] for a in np.linspace(0,2*math.pi,48,endpoint=False)])
        # Directional visibility is only an estimated planning cost, never an exclusion rule.
        admissible=[]
        for g in samples:
            mask=np.all((previous-g)@normals.T>=-1e-7,axis=0)
            admissible.append(mask)
        best=None;best_score=float('inf');seen=set()
        for q in candidates:
            key=tuple(np.round(q,3))
            if key in seen:continue
            seen.add(key)
            if any(np.linalg.norm(q-p)<.1 for p in self.measured[c]):continue
            move=float(np.linalg.norm(q-current))/5
            radii=[];visible=[]
            for g,mask in zip(samples,admissible):
                delta=g-q
                beta=math.degrees(math.atan2(delta[1],delta[0]))%360
                post=bearing_clip(poly,q,beta,2*EPS_DEG)
                if len(post):
                    m=post.mean(axis=0)
                    radii.append(float(np.max(np.linalg.norm(post-m,axis=1))))
                else:radii.append(radius)
                lower=max(1000.,float(np.max(np.linalg.norm(previous-g,axis=1))))
                distance=float(np.linalg.norm(q-g))
                distance_weight=1. if distance<=lower else max(0.,(1500.-distance)/max(1.,1500.-lower))
                if self.problem==4 and np.any(mask):
                    orientation=float(np.mean((q-g)@normals[mask].T>=0))
                else:orientation=1.
                visible.append(distance_weight*orientation)
            rpred=float(np.mean(radii));prob=float(np.mean(visible))
            remaining=float(np.mean(np.linalg.norm(samples-q,axis=1)))/5
            score=move+5+int(c!=self.channel)+remaining+.4*rpred+15*(rpred>20)
            score+=(1-prob)*(45+move+.2*radius)
            self.diagnostics['candidate_evaluations']+=1
            if score<best_score:best_score=score;best=q
        return best

    def locate(self,c):
        if self.profile.startswith('directional'):
            return self.locate_directional(c)
        dark=0
        for _ in range(self.max_refine):
            poly,center,radius=self.region(c)
            if radius<=19.99:
                self.certified_clear(c,poly,center,radius);return
            q=self.next_measure(c,poly,center,radius)
            if q is None:break
            r=self.action('/measure',q,c)
            if r['measure_result']=='near':
                if not self.clear(self.pos,c):raise RuntimeError('Near clear failed')
                return
            if r['measure_result']=='no_signal':
                dark+=1
                if dark>=2:break
            else:dark=0
        poly,center,radius=self.region(c)
        if radius<=19.99:
            self.certified_clear(c,poly,center,radius);return
        self.counts['fallback']+=1
        points=optical_cover(poly,self.obs[c][0][1])
        if self.profile.endswith('safe'):
            # Keep EVERY original center; only its visiting order is changed.
            points=points[open_route(points,self.pos)]
        elif np.linalg.norm(points[-1]-self.pos)<np.linalg.norm(points[0]-self.pos):
            points=points[::-1]
        for p in points:
            if self.clear(p,c):return
        raise RuntimeError('Exhausted optical cover')

    def locate_directional(self,c):
        # A cheap stationary reading can reuse the travel already made for another target.
        if (np.linalg.norm(self.pos-self.obs[c][-1][0])>80
                and not any(np.linalg.norm(self.pos-p)<.1 for p in self.measured[c])):
            r=self.action('/measure',self.pos,c)
            if r['measure_result']=='near':
                if not self.clear(self.pos,c):raise RuntimeError('Near clear failed')
                return
        for _ in range(self.max_refine):
            poly,center,radius=self.region(c)
            if radius<=19.99:
                self.certified_clear(c,poly,center,radius);return
            p0=self.obs[c][-1][0];d=center-p0;length=np.linalg.norm(d)
            if length<1e-8:break
            v=np.array([-d[1],d[0]])/length
            options=[p0+.8*d+sign*min(100.,.35*length)*v for sign in (-1,1)]
            options.sort(key=lambda p:np.linalg.norm(p-self.pos))
            positive=False
            for q in options:
                r=self.action('/measure',q,c)
                if r['measure_result']=='near':
                    if not self.clear(self.pos,c):raise RuntimeError('Near clear failed')
                    return
                if r['measure_result']=='direction':positive=True;break
            if not positive:break
        poly,center,radius=self.region(c)
        if radius<=19.99:
            self.certified_clear(c,poly,center,radius);return
        self.counts['fallback']+=1
        points=optical_cover(poly,self.obs[c][0][1])
        if self.profile.endswith('safe'):points=points[open_route(points,self.pos)]
        elif np.linalg.norm(points[-1]-self.pos)<np.linalg.norm(points[0]-self.pos):points=points[::-1]
        for p in points:
            if self.clear(p,c):return
        raise RuntimeError('Exhausted optical cover')

    def next_station(self):
        pending=self.pending_stations
        if 'layers' in self.profile:
            inner=[i for i in pending if np.linalg.norm(self.stations[i])<=1800]
            eligible=inner or pending
            return eligible[open_route(self.stations[eligible],self.pos)[0]]
        if 'tour' in self.profile:
            return next(i for i in self.coverage_order if i in pending)
        if self.profile in ('local','directional'):
            return min(pending,key=lambda i:np.linalg.norm(self.stations[i]-self.pos))
        order=open_route(self.stations[pending],self.pos)
        return pending[order[0]]

    def process_found(self,found):
        while found:
            centers=np.array([self.region(c)[1] for c in found])
            if self.profile in ('local','directional'):
                index=int(np.argmin(np.linalg.norm(centers-self.pos,axis=1)))
            else:
                end=self.stations[self.next_station()] if self.pending_stations else None
                index=open_route(centers,self.pos,end=end)[0]
            c=found.pop(index)
            self.locate(c)
            if 'opportunistic' in self.profile:
                for extra in range(1,21):
                    if extra in self.cleared or self.obs[extra]:continue
                    if self.measured[extra] and min(np.linalg.norm(self.pos-p) for p in self.measured[extra])<650:continue
                    r=self.action('/measure',self.pos,extra)
                    self.diagnostics['opportunistic_measures']+=1
                    if r['measure_result']=='near':
                        if not self.clear(self.pos,extra):raise RuntimeError('Near clear failed')
                    elif r['measure_result']=='direction':found.append(extra)

    def run(self):
        start=time.perf_counter();entered=self.api.enter()
        self.deadline=time.monotonic()+entered['remaining_real_duration_s']
        self.pending_stations=list(range(len(self.stations)))
        joint=self.profile in ('joint','joint_safe')
        while self.pending_stations or self.deferred:
            self.deferred={c:age for c,age in self.deferred.items() if c not in self.cleared}
            if len(self.cleared)==16:break
            if joint and self.deferred:
                keys=list(self.deferred)
                overdue=[c for c in keys if len(self.visited)-self.deferred[c]>=self.max_defer_stations]
                if overdue or not self.pending_stations:
                    forced=overdue or keys
                    c=min(forced,key=lambda c:np.linalg.norm(self.region(c)[1]-self.pos))
                    self.diagnostics['forced_targets']+=1
                    self.locate(c);self.deferred.pop(c,None);continue
                nodes=[('target',c) for c in keys]+[('station',j) for j in self.pending_stations]
                points=np.array([self.region(c)[1] for c in keys]+[self.stations[j] for j in self.pending_stations])
                kind,which=nodes[open_route(points,self.pos)[0]]
                if kind=='target':
                    self.locate(which);self.deferred.pop(which,None);continue
                i=which
            elif self.pending_stations:i=self.next_station()
            else:break
            self.pending_stations.remove(i);p=self.stations[i]
            found=[]
            channels=[c for c in range(1,21) if c not in self.cleared]
            if self.channel in channels:
                channels.remove(self.channel);channels.insert(0,self.channel)
            for c in channels:
                r=self.action('/measure',p,c)
                if r['measure_result']=='near':
                    if not self.clear(p,c):raise RuntimeError('Near clear failed')
                elif r['measure_result']=='direction':found.append(c)
                if c in self.deferred:self.diagnostics['opportunistic_measures']+=1
            self.visited.append(i)
            if joint:
                for c in found:
                    if c not in self.deferred:
                        self.deferred[c]=len(self.visited)
                        self.diagnostics['deferred_targets']+=1
            else:self.process_found(found)
            if len(self.cleared)==16:break
        if len(self.cleared)<16 and (self.pending_stations or any(c not in self.cleared for c in self.deferred)):
            raise RuntimeError('Cannot finish with unresolved coverage or targets')
        # HTTP failures propagate; do not send a new action after an uncertain response.
        self.api.exit()
        total=self.api.virtual_time
        return dict(problem=self.problem,strategy=self.profile,cleared=len(self.cleared),
                    virtual_time_s=total,mean_time_s=total/len(self.cleared) if self.cleared else None,
                    program_time_s=time.perf_counter()-start,complete=True,
                    stations_visited=len(self.visited),**self.counts,**self.parts,**self.diagnostics)

