"""Verify refactoring by exact action traces, not only final counts."""
import sys,importlib.util,json,math
from pathlib import Path
import numpy as np
from backend import LocalBackend
from audit import AuditPort
from optimized_solver import Solver as Reference
root=Path(__file__).parent;support=root.parents[1]/'成果'/'support'
spec=importlib.util.spec_from_file_location('maintained_solver',support/'solver.py')
module=importlib.util.module_from_spec(spec);spec.loader.exec_module(module)
rows=[]
for problem in (3,4):
    for kind in ('random','positive_boundary','negative_tangent','cluster','correlated'):
        for i in range(20):
            seed=920000+1000*problem+100*('random','positive_boundary','negative_tangent','cluster','correlated').index(kind)+i
            traces=[]
            for name in ('reference','maintained'):
                b=LocalBackend(seed,problem,n=10+i%7,error_mode='minus' if kind=='negative_tangent' else 'plus' if kind=='positive_boundary' else 'fixed',radius=1000. if kind!='random' else None,all_directional=kind!='random')
                if kind in ('positive_boundary','negative_tangent'):
                    for j,s in enumerate(b.sources.values()):
                        theta=2*math.pi*j/len(b.sources);s['p']=1800*np.array([math.cos(theta),math.sin(theta)])
                        if problem==4:s['direction']=theta+(math.pi/2 if kind=='negative_tangent' else 0)
                if kind=='cluster':
                    for j,s in enumerate(b.sources.values()):s['p']=np.array([.01,0.]) if j==0 else np.array([900.+j,300.])
                if kind=='correlated':b.error=lambda p,c:math.sin(p[0]/400+p[1]/700+c)
                a=AuditPort(b)
                solver=Reference(a,problem,'joint_safe' if problem==3 else 'directional_layers_safe') if name=='reference' else module.Solver(a,problem)
                r=solver.run();assert r['cleared']==len(b.sources) and a.exited,r
                traces.append(b.trace)
                if name=='maintained':rows.append({'problem':problem,'scenario':kind,'seed':seed,'cleared':r['cleared'],'total':len(b.sources),'virtual_time_s':r['virtual_time_s'],'normal_exit':a.exited})
            assert traces[0]==traces[1],(problem,kind,seed)
        print(json.dumps({'problem':problem,'setting':kind,'trace_matches':20}),flush=True)
out=support/'results'/'validation';out.mkdir(parents=True,exist_ok=True)
(out/'integration.json').write_text(json.dumps({'cases':len(rows),'runs':2*len(rows),'all_cleared':True,'exact_action_trace_match':True,'rows':rows},indent=2),encoding='utf-8')
